const state = JSON.parse(localStorage.getItem('rea-hub') || '{"harnesses":[],"artifacts":[],"runs":0}');
const $ = (s) => document.querySelector(s);
const save = () => localStorage.setItem('rea-hub', JSON.stringify(state));
function show(view){document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===view));document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===view));if(view==='overview') renderOverview();if(view==='artifacts') renderArtifacts();}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>show(b.dataset.view));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>show(b.dataset.go));
function renderOverview(){ $('#metricArtifacts').textContent=state.artifacts.length;$('#metricHarnesses').textContent=state.harnesses.length;$('#metricRuns').textContent=state.runs;const box=$('#recent');box.innerHTML='<div class="row head"><div>Artifact</div><div>Target</div><div>Status</div><div>Updated</div></div>'+(state.harnesses.length?state.harnesses.slice().reverse().map(h=>`<div class="row"><div><strong>${esc(h.name)}</strong><br><span class="muted">${esc(h.artifact)}</span></div><div><span class="pill">${esc(h.target)}</span></div><div><span class="pill">READY</span></div><div class="muted">${h.time}</div></div>`).join(''):'<div class="row muted"><div>No harnesses yet. Create your first investigation.</div><div>—</div><div>—</div><div>now</div></div>');}
function renderArtifacts(){const box=$('#artifactList');box.innerHTML=state.artifacts.length?state.artifacts.map(a=>`<div class="row" style="padding-left:0;padding-right:0"><div><strong>${esc(a.name)}</strong><br><span class="muted">${esc(a.kind)}</span></div><div class="muted">${a.size||'URL reference'}</div></div>`).join(''):'No artifacts added yet.';}
function esc(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
let selectedFile=null;$('#drop').onclick=()=>$('#file').click();$('#file').onchange=e=>{selectedFile=e.target.files[0];if(selectedFile)$('#drop').querySelector('strong').textContent=selectedFile.name};
$('#harnessForm').onsubmit=e=>{e.preventDefault();const name=$('#name').value.trim();const url=$('#url').value.trim();const artifact=selectedFile?.name||url||'unattached evidence';const h={id:crypto.randomUUID(),name,target:$('#target').value,mode:$('#mode').value,artifact,brief:$('#brief').value,steps:[...document.querySelectorAll('.chips input:checked')].map(x=>x.value),time:new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})};state.harnesses.push(h);if(selectedFile)state.artifacts.push({name:selectedFile.name,kind:selectedFile.type||'file',size:`${Math.ceil(selectedFile.size/1024)} KB`});else if(url)state.artifacts.push({name:url,kind:'URL',size:'remote'});save();$('#runTitle').textContent=h.name;$('#log').textContent=`Harness ${h.id}\nSaved locally. Adapter ready.`;location.hash=`harness=${btoa(unescape(encodeURIComponent(JSON.stringify(h))))}`;show('runs');renderOverview()};
$('#runBtn').onclick=()=>{if(!state.harnesses.length){$('#log').textContent='Create a harness first.';return}const h=state.harnesses[state.harnesses.length-1];state.runs++;save();const lines=[['info','[00:00:00] dispatching dry-run adapter'],['info',`[00:00:01] target: ${h.target}`],['info',`[00:00:01] artifact: ${h.artifact}`],['ok',`[00:00:02] steps accepted: ${h.steps.join(', ')}`],['ok','[00:00:02] evidence manifest created'],['ok','[00:00:02] dry run complete — connect /api/runs for native execution']];$('#log').innerHTML=lines.map(x=>`<span class="${x[0]}">${esc(x[1])}</span>`).join('\n');renderOverview()};
$('#exportBtn').onclick=()=>{const data={name:$('#name').value,target:$('#target').value,mode:$('#mode').value,url:$('#url').value,brief:$('#brief').value,steps:[...document.querySelectorAll('.chips input:checked')].map(x=>x.value)};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=(data.name||'rea-harness').replace(/\W+/g,'-')+'.json';a.click()};
renderOverview();

const workerBox=document.createElement('div'); workerBox.className='muted'; workerBox.style='margin-top:14px;display:flex;gap:8px;flex-wrap:wrap;align-items:center'; workerBox.innerHTML='<span>REA worker URL</span><input id="workerUrl" placeholder="https://your-worker.onrender.com" style="min-width:280px;background:#0d1310;border:1px solid var(--line);color:var(--text);border-radius:9px;padding:9px"><button class="ghost" id="saveWorkerUrl" type="button">Save worker</button>'; $('#runs .card').appendChild(workerBox); $('#workerUrl').value=localStorage.getItem('rea-worker-url')||''; $('#saveWorkerUrl').onclick=()=>{localStorage.setItem('rea-worker-url',$('#workerUrl').value.trim().replace(/\/$/,''));$('#saveWorkerUrl').textContent='Saved';setTimeout(()=>$('#saveWorkerUrl').textContent='Save worker',1000)};
const localStartREA=startREA;
startREA=async function(){
  localStartREA(); const worker=localStorage.getItem('rea-worker-url'); if(!worker||!state.harnesses.length)return;
  const h=state.harnesses[state.harnesses.length-1]; $('#log').innerHTML+='\n<span class="info">[00:00:03] sending artifact to REA worker…</span>';
  try { const payload={filename:h.artifact,provider:h.target==='Ghidra'?'ghidra':'ghidra',url:/^https?:\/\//i.test(h.artifact)?h.artifact:undefined}; if(selectedFile){payload.contentBase64=btoa(String.fromCharCode(...new Uint8Array(await selectedFile.arrayBuffer())));delete payload.url;} const response=await fetch(`${worker}/jobs`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}); const result=await response.json(); if(!response.ok)throw new Error(result.error||'worker request failed'); $('#log').innerHTML+='\n<span class="ok">[00:00:04] REA worker completed; evidence returned</span>'; $('#log').innerHTML+='\n'+esc(result.evidence||''); } catch(error){ $('#log').innerHTML+=`\n<span class="info">[00:00:03] worker unavailable: ${esc(error.message)}. Local handoff remains ready.</span>`; }
}; $('#runBtn').onclick=()=>startREA();

// v0.3: keep the UI aligned with REA's actual provider model.
const targetSelect = $('#target');
[['Hopper','Hopper — native analysis (license/auth required)'],['IDA','IDA — native analysis (license/auth required)']].forEach(([value,label])=>{
  if (![...targetSelect.options].some(o=>o.value===value)) targetSelect.add(new Option(label,value));
});
const promptNav=document.createElement('button'); promptNav.dataset.view='prompt'; promptNav.textContent='Super prompt'; document.querySelector('nav').insertBefore(promptNav,document.querySelector('nav button[data-view="artifacts"]')); promptNav.onclick=()=>show('prompt');
const promptView=document.createElement('section'); promptView.className='view'; promptView.id='prompt'; promptView.innerHTML=`<header class="top"><div><div class="eyebrow">prompt workbench / 05</div><h1>Start REA from Codex or Claude.</h1><p>Generate a copy-ready operating prompt from the current harness. It tells the coding agent how to use the local REA repository, Ghidra, Hopper, and IDA safely.</p></div></header><div class="card"><div class="field"><label>Prompt destination</label><select id="promptAgent"><option>Codex</option><option>Claude</option><option>Generic coding agent</option></select></div><div class="field" style="margin-top:14px"><label>Generated super prompt</label><textarea id="superPrompt" rows="16" spellcheck="false"></textarea></div><div class="actions"><button class="ghost" id="copyPrompt">Copy prompt</button><button class="primary" id="refreshPrompt">Generate prompt</button></div></div>`; document.querySelector('.main').appendChild(promptView);
function buildPrompt(){const h=state.harnesses[state.harnesses.length-1]||{name:'new investigation',artifact:'the supplied artifact',target:$('#target').value,steps:[...document.querySelectorAll('.chips input:checked')].map(x=>x.value),brief:$('#brief').value}; const agent=$('#promptAgent').value; return `You are ${agent}, operating as a careful reverse-engineering lead. Start an REA investigation for: ${h.name}.\n\nArtifact: ${h.artifact}\nPrimary tool: ${h.target}\nSteps: ${h.steps.join(', ')||'inventory, evidence report'}\nBrief: ${h.brief||'Determine behavior, attack surface, and verifiable findings.'}\n\nConnect the local REA repository and use its MCP/CLI workflow. Use Ghidra first for native analysis; Ghidra is free and local, so do not request a password. REA also supports Hopper and IDA; if either is selected, stop and ask the user to provide/authorize the required installation and license authentication—never ask for passwords or tokens in chat. Use JADX for APKs and the browser provider for websites when relevant. Never execute unknown binaries on the host; isolate them, preserve hashes, and ask before any destructive or external action. Keep a timestamped evidence trail. Separate observations, hypotheses, and confirmed findings. End with: executive summary, commands/tools used, evidence paths, limitations, and next steps. Do not claim a tool ran unless its output is present.`}
$('#refreshPrompt').onclick=()=>$('#superPrompt').value=buildPrompt(); $('#copyPrompt').onclick=async()=>{await navigator.clipboard.writeText($('#superPrompt').value);$('#copyPrompt').textContent='Copied';setTimeout(()=>$('#copyPrompt').textContent='Copy prompt',1200)}; $('#promptAgent').onchange=()=>$('#superPrompt').value=buildPrompt(); $('#superPrompt').value=buildPrompt();

// One-click flow: intake -> REA handoff manifest -> Codex continuation prompt.
$('#runBtn').textContent='Start REA workflow';
function startREA(){
  if(!state.harnesses.length){$('#log').textContent='Upload an app/file or add a URL, then save the harness first.';return}
  const h=state.harnesses[state.harnesses.length-1]; state.runs++; save();
  const steps=h.steps.length?h.steps.join(', '):'inventory, evidence report';
  const lines=[
    ['info','[00:00:00] REA handoff prepared'],
    ['info',`[00:00:01] artifact: ${h.artifact}`],
    ['info',`[00:00:01] target: ${h.target}`],
    ['ok',`[00:00:02] requested analysis: ${steps}`],
    ['ok','[00:00:02] evidence manifest created'],
    ['ok','[00:00:02] Codex/Claude continuation prompt ready'],
    ['info','[00:00:02] connect a local REA worker to execute native analysis']
  ];
  $('#runTitle').textContent=`REA workflow · ${h.name}`;
  $('#log').innerHTML=lines.map(x=>`<span class="${x[0]}">${esc(x[1])}</span>`).join('\n');
  $('#superPrompt').value=buildPrompt();
  location.hash=`harness=${btoa(unescape(encodeURIComponent(JSON.stringify(h))))}`;
  show('runs'); renderOverview();
}
$('#runBtn').onclick=startREA;
$('#harnessForm').onsubmit=e=>{e.preventDefault();
  const name=$('#name').value.trim(); const url=$('#url').value.trim(); const artifact=selectedFile?.name||url||'unattached evidence';
  const h={id:crypto.randomUUID(),name,target:$('#target').value,mode:$('#mode').value,artifact,brief:$('#brief').value,steps:[...document.querySelectorAll('.chips input:checked')].map(x=>x.value),time:new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})};
  state.harnesses.push(h); if(selectedFile)state.artifacts.push({name:selectedFile.name,kind:selectedFile.type||'file',size:`${Math.ceil(selectedFile.size/1024)} KB`}); else if(url)state.artifacts.push({name:url,kind:'URL',size:'remote'}); save(); startREA();
};

renderOverview = function(){ const box=$('#recent'); $('#metricArtifacts').textContent=state.artifacts.length; $('#metricHarnesses').textContent=state.harnesses.length; $('#metricRuns').textContent=state.runs; box.innerHTML='<div class="row head"><div>Artifact</div><div>Target</div><div>Status</div><div>Updated</div></div>'+(state.harnesses.length?state.harnesses.slice().reverse().map(h=>`<div class="row"><div><strong>${esc(h.name)}</strong><br><span class="muted">${esc(h.artifact)}</span></div><div><span class="pill">${esc(h.target)}</span></div><div><span class="pill">READY</span><br><button class="ghost delete-harness" data-id="${esc(h.id)}" type="button">Delete</button></div><div class="muted">${h.time}</div></div>`).join(''):'<div class="row muted"><div>No harnesses yet. Create your first investigation.</div><div>—</div><div>—</div><div>now</div></div>'); };
document.addEventListener('click',e=>{ const b=e.target.closest('.delete-harness'); if(!b)return; const h=state.harnesses.find(x=>x.id===b.dataset.id); if(!h)return; if(!confirm(`Delete harness “${h.name}”?`))return; state.harnesses=state.harnesses.filter(x=>x.id!==h.id); state.artifacts=state.artifacts.filter(a=>a.name!==h.artifact); save(); renderOverview(); $('#runTitle').textContent='No run selected'; $('#log').textContent='Harness deleted. Create or keep another harness to continue.'; });
renderOverview();
